const BASE = RAW.split(";").map((line) => {
  const [code, name, icS, shS, mxS, tkS] = line.split("|");
  const ic = icS.split(",").map((n) => +n / 1e6);
  const sh = shS.split(",").map((n) => +n / 1e4);
  const mx = mxS.split(",").map((n) => +n / 1e4);
  const tk = tkS.split(",").map((n) => +n / 100);
  return {
    code,
    name,
    // matriz IC+Fee 5x4 (null = combinação não existe)
    ic: [
      [ic[0], ic[1], ic[2], ic[3]],
      [ic[0], ic[1], ic[2], ic[3]],
      [ic[4], ic[5], ic[6], ic[7]],
      [null, ic[8], ic[9], ic[10]],
      [null, ic[11], ic[12], ic[13]],
    ],
    shb: [sh.slice(0, 4), sh.slice(4, 8), sh.slice(8, 12), sh.slice(12, 16), sh.slice(16, 20)],
    mix: mx,
    tkt: tk,
  };
});
const BY_CODE = Object.fromEntries(BASE.map((m) => [m.code, m]));

