const C = {
  ink: "#16232E",
  paper: "#E9ECEE",
  card: "#FFFFFF",
  rule: "#CBD3D8",
  soft: "#F3F5F6",
  mute: "#61737E",
  ok: "#0B6E62",
  warn: "#B06A12",
  bad: "#93283A",
};

const brl = (v) =>
  (v < 0 ? "-" : "") +
  "R$ " +
  Math.abs(v).toLocaleString("pt-BR", { minimumFractionDigits: 0, maximumFractionDigits: 0 });
const pct = (v, d = 3) => (v * 100).toFixed(d).replace(".", ",") + "%";
