  const [cTpv, setCTpv] = useState(0.00034783);
  const [cPos, setCPos] = useState(0);
  const [cac, setCac] = useState(3030.55);
  const [imposto, setImposto] = useState(0.1125);
  const [margemMin, setMargemMin] = useState(0.0015);
  const [paybackMax, setPaybackMax] = useState(14);

  const [open, setOpen] = useState({ mix: true, preco: true, prod: false, custo: false, alc: false });
